    /// This is a legacy parameter. Use ConditionExpression instead. For more information, see ConditionalOperator in the Amazon DynamoDB De- veloper Guide . Possible values: o AND o OR
    /// </summary>
    [CliOption("--conditional-operator")]
    public AwsDynamodbUpdateItemConditionalOperator? ConditionalOperator { get; set; }

    /// <summary>
    /// Use ReturnValues if you want to get the item attributes as they ap- pear before or after they are successfully updated. For UpdateItem , the valid values are: o NONE - If ReturnValues is not specified, or if its value is NONE , then nothing is returned. (This setting is the default for Return- Values .) o ALL_OLD - Returns all of the attributes of the item, as they ap- peared before the UpdateItem operation. o UPDATED_OLD - Returns only the updated attributes, as they ap- peared before the UpdateItem operation. o ALL_NEW - Returns all of the attributes of the item, as they ap- pear after the UpdateItem operation. o UPDATED_NEW - Returns only the updated attributes, as they appear after the UpdateItem operation. There is no additional cost associated with requesting a return value aside from the small network and processing overhead of re- ceiving a larger response. No read capacity units are consumed. The values returned are strongly consistent. Possible values: o NONE o ALL_OLD o UPDATED_OLD o ALL_NEW o UPDATED_NEW
    /// </summary>
    [CliOption("--return-values")]
    public AwsDynamodbUpdateItemReturnValues? ReturnValues { get; set; }

    /// <summary>
    /// Determines the level of detail about either provisioned or on-demand throughput consumption that is returned in the response: o INDEXES - The response includes the aggregate ConsumedCapacity for the operation, together with ConsumedCapacity for each table and secondary index that was accessed. Note that some operations, such as GetItem and BatchGetItem , do not access any indexes at all. In these cases, specifying INDEXES will only return ConsumedCapacity information for table(s). o TOTAL - The response includes only the aggregate ConsumedCapacity for the operation. o NONE - No ConsumedCapacity details are included in the response. Possible values: o INDEXES o TOTAL o NONE
    /// </summary>
    [CliOption("--return-consumed-capacity")]
    public AwsDynamodbUpdateItemReturnConsumedCapacity? ReturnConsumedCapacity { get; set; }

    /// <summary>
    /// Determines whether item collection metrics are returned. If set to SIZE , the response includes statistics about item collections, if any, that were modified during the operation are returned in the re- sponse. If set to NONE (the default), no statistics are returned. Possible values: o SIZE o NONE
    /// </summary>
    [CliOption("--return-item-collection-metrics")]
    public AwsDynamodbUpdateItemReturnItemCollectionMetrics? ReturnItemCollectionMetrics { get; set; }

    /// <summary>
    /// An expression that defines one or more attributes to be updated, the action to be performed on them, and new values for them. The following action values are available for UpdateExpression . o SET - Adds one or more attributes and values to an item. If any of these attributes already exist, they are replaced by the new val- ues. You can also use SET to add or subtract from an attribute that is of type Number. For example: SET myNum = myNum + :val SET supports the following functions: o if_not_exists (path, operand) - if the item does not contain an attribute at the specified path, then if_not_exists evaluates to operand; otherwise, it evaluates to path. You can use this func- tion to avoid overwriting an attribute that may already be present in the item. o list_append (operand, operand) - evaluates to a list with a new element added to it. You can append the new element to the start or the end of the list by reversing the order of the operands. These function names are case-sensitive. o REMOVE - Removes one or more attributes from an item. o ADD - Adds the specified value to the item, if the attribute does not already exist. If the attribute does exist, then the behavior of ADD depends on the data type of the attribute: o If the existing attribute is a number, and if Value is also a number, then Value is mathematically added to the existing at- tribute. If Value is a negative number, then it is subtracted from the existing attribute. NOTE: If you use ADD to increment or decrement a number value for an item that doesn't exist before the update, DynamoDB uses 0 as the initial value. Similarly, if you use ADD for an existing item to increment or decrement an attribute value that doesn't exist before the update, DynamoDB uses 0 as the initial value. For example, suppose that the item you want to update doesn't have an attribute named itemcount , but you decide to ADD the number 3 to this attribute anyway. DynamoDB will create the itemcount attribute, set its initial value to 0 , and finally add 3 to it. The result will be a new itemcount attribute in the item, with a value of 3 . o If the existing data type is a set and if Value is also a set, then Value is added to the existing set. For example, if the at- tribute value is the set [1,2] , and the ADD action specified [3] , then the final attribute value is [1,2,3] . An error oc- curs if an ADD action is specified for a set attribute and the attribute type specified does not match the existing set type. Both sets must have the same primitive data type. For example, if the existing data type is a set of strings, the Value must also be a set of strings. WARNING: The ADD action only supports Number and set data types. o DELETE - Deletes an element from a set. If a set of values is specified, then those values are subtracted from the old set. For example, if the attribute value was the set [a,b,c] and the DELETE action specifies [a,c] , then the final attribute value is [b] . Specifying an empty set is an error. WARNING: The DELETE action only supports set data types. You can have many actions in a single expression, such as the fol- lowing: SET a=:value1, b=:value2 DELETE :value3, :value4, :value5 For more information on update expressions, see Modifying Items and Attributes in the Amazon DynamoDB Developer Guide .
    /// </summary>
    [CliOption("--update-expression")]
    public string? UpdateExpression { get; set; }

    /// <summary>
    /// A condition that must be satisfied in order for a conditional update to succeed. An expression can contain any of the following: o Functions: attribute_exists | attribute_not_exists | at- tribute_type | contains | begins_with | size These function names are case-sensitive. o Comparison operators: = | &lt;&gt; | &lt; | &gt; | &lt;= | &gt;= | BETWEEN | IN o Logical operators: AND | OR | NOT For more information about condition expressions, see Specifying Conditions in the Amazon DynamoDB Developer Guide .
    /// </summary>
    [CliOption("--condition-expression")]
    public string? ConditionExpression { get; set; }

    /// <summary>
    /// One or more substitution tokens for attribute names in an expres- sion. The following are some use cases for using ExpressionAttribut- eNames : o To access an attribute whose name conflicts with a DynamoDB re- served word. o To create a placeholder for repeating occurrences of an attribute name in an expression. o To prevent special characters in an attribute name from being mis- interpreted in an expression. Use the # character in an expression to dereference an attribute name. For example, consider the following attribute name: o Percentile The name of this attribute conflicts with a reserved word, so it cannot be used directly in an expression. (For the complete list of reserved words, see Reserved Words in the Amazon DynamoDB Developer Guide .) To work around this, you could specify the following for ExpressionAttributeNames : o {"#P":"Percentile"} You could then use this substitution in an expression, as in this example: o #P = :val NOTE: Tokens that begin with the : character are expression attribute values , which are placeholders for the actual value at runtime. For more information about expression attribute names, see Specifying Item Attributes in the Amazon DynamoDB Developer Guide . key -&gt; (string) value -&gt; (string) Constraints: o max: 65535 Shorthand Syntax: KeyName1=string,KeyName2=string JSON Syntax: {"string": "string" ...}
    /// </summary>
    [CliOption("--expression-attribute-names", CollectionSeparator = ",")]
